#!/usr/bin/env node
/*
 * render_day2_bonus_final.mjs — render Day2 bonus 《鲸鱼选鱼》 final voiced cut.
 *
 * Gates:
 * - timing must be the 9-cue measured alignment of the user-provided final WAV,
 *   with measured clause-level subtitle segments and no inserted dialogue pause;
 * - audio must come from assets/day2_bonus_final_track.wav generated by
 *   gen_bonus_finalvoice.py (source WAV itself is never modified);
 * - output names containing 样片/无配音/Piper/draft/初步草稿 are rejected so
 *   this final renderer cannot silently overwrite a sample or placeholder.
 */
import { createRequire } from 'node:module';
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
// Snapshot convention: this renderer may be copied either to the video-fx
// repository root or beside the chapter in src/ch. Resolve the real root.
const ROOT = fs.existsSync(path.join(HERE, 'src', 'core.js'))
  ? HERE
  : path.resolve(HERE, '..', '..');
const requireFromHere = createRequire(import.meta.url);
const requireFromRoot = createRequire(path.join(ROOT, 'package.json'));

function argValue(flag, fallback = null) {
  const i = process.argv.indexOf(flag);
  return i >= 0 ? process.argv[i + 1] : fallback;
}
const STILLS = process.argv.includes('--stills');
const VARIANT = 'oldactions';
const OUT = argValue('--out', path.join(ROOT, 'Day2加更_鲸鱼选鱼_最终配音版.mp4'));
if (!STILLS) {
  const base = path.basename(OUT);
  const lower = base.toLowerCase();
  if (base.includes('样片') || base.includes('无配音') || base.includes('初步草稿') ||
      lower.includes('piper') || lower.includes('draft') || lower.includes('silent')) {
    throw new Error(`final voiced output must not use a sample/placeholder name: ${base}`);
  }
}

let createCanvas, loadImage, GlobalFonts;
try {
  ({ createCanvas, loadImage, GlobalFonts } = requireFromRoot('@napi-rs/canvas'));
} catch {
  ({ createCanvas, loadImage, GlobalFonts } = requireFromHere('@napi-rs/canvas'));
}

const FONT_DIR = path.join(ROOT, 'assets', 'fonts');
function registerFont(file, families) {
  const fontPath = path.join(FONT_DIR, file);
  if (!fs.existsSync(fontPath) || !GlobalFonts?.registerFromPath) return;
  for (const family of families) GlobalFonts.registerFromPath(fontPath, family);
}
registerFont('ZCOOLKuaiLe-Regular.ttf', ['ZCOOLKuaiLe', 'ZCOOL KuaiLe']);
registerFont('NotoSansSC-Bold.ttf', ['NotoSansSC', 'Noto Sans SC', 'Noto Sans CJK SC', 'Microsoft YaHei']);
registerFont('NotoSansSC-Regular.ttf', ['NotoSansSC', 'Noto Sans SC', 'Noto Sans CJK SC', 'Microsoft YaHei']);
registerFont('Silkscreen-Regular.ttf', ['Silkscreen']);

globalThis.window = globalThis;
globalThis.DAY2_CHARACTER_MODE = 'mixed';
requireFromRoot('./assets/audio_envelope.js');
requireFromRoot('./assets/day2_bonus_final_envelope.js'); // measured final-voice envelope
const FINAL_TIMING = requireFromRoot('./src/day2_bonus_final_timing.js');
const CORE = requireFromRoot('./src/core.js');
const WHALE_RIG = requireFromRoot('./src/whale_girl_rig_data.js');
if (WHALE_RIG?.poses?.wink && WHALE_RIG?.poses?.heart?.backHair) {
  WHALE_RIG.poses.wink.backHair = WHALE_RIG.poses.heart.backHair;
}
// Eye-line gate: keep the wink pose's hands-on-hips body bones, but use the
// open-eyed wave head so the old lead never gets a closed-eye/skin-band head.
if (WHALE_RIG?.poses?.wink && WHALE_RIG?.poses?.wave?.head) {
  WHALE_RIG.poses.wink.head = WHALE_RIG.poses.wave.head;
}
requireFromRoot('./src/whale_girl_actions.js');
requireFromRoot('./src/whale_girl.js');
requireFromRoot('./src/clawd.js');
requireFromRoot('./src/cast.js');
requireFromRoot('./src/lyrics.js');
requireFromRoot('./src/props.js');
const TIMELINE = requireFromRoot('./src/timeline.js');

const DAY2_POSE_NAMES = [
  'idle-cute', 'curious', 'thinking', 'running', 'success', 'failure', 'blush',
  'angry', 'eat', 'celebrate', 'sleep', 'greet', 'wink', 'bold', 'star',
  'daily-gaming', 'daily-eat', 'daily-stretch', 'tail-swing', 'meme-cry',
  'meme-smug', 'meme-doge', 'meme-heart', 'meme-no', 'meme-yes', 'meme-music',
  'work-debug', 'work-idea', 'work-review', 'work-deadline', 'react-head',
  'react-belly', 'react-tail', 'game-happy', 'game-win', 'teasing',
  'daily-done', 'levelup', 'cool-shades'
];
function alphaBBox(img) {
  const c = createCanvas(img.width, img.height);
  const g = c.getContext('2d');
  g.drawImage(img, 0, 0);
  const d = g.getImageData(0, 0, img.width, img.height).data;
  let x0 = img.width, y0 = img.height, x1 = -1, y1 = -1;
  for (let y = 0; y < img.height; y++) {
    for (let x = 0; x < img.width; x++) {
      if (d[(y * img.width + x) * 4 + 3] > 8) {
        if (x < x0) x0 = x;
        if (x > x1) x1 = x;
        if (y < y0) y0 = y;
        if (y > y1) y1 = y;
      }
    }
  }
  if (x1 < 0) return { x: 0, y: 0, w: img.width, h: img.height };
  return { x: x0, y: y0, w: x1 - x0 + 1, h: y1 - y0 + 1 };
}
async function loadDay2Poses() {
  const dir = path.join(ROOT, 'assets', 'day2_poses');
  const out = {};
  await Promise.all(DAY2_POSE_NAMES.map(async name => {
    const file = path.join(dir, `dsh-whale-state-${name}.webp`);
    if (!fs.existsSync(file)) throw new Error(`Day2 pose missing: ${file}`);
    const img = await loadImage(file);
    if (img.width !== 512 || img.height !== 512) {
      throw new Error(`Day2 pose ${name} should be 512x512, got ${img.width}x${img.height}`);
    }
    out[name] = { img, bbox: alphaBBox(img), file: path.basename(file) };
  }));
  return out;
}
globalThis.DAY2_POSES = await loadDay2Poses();
globalThis.DAY2_POSE_COUNT = DAY2_POSE_NAMES.length;

// ---------------------------------------------------------------------------
// 高清说话人：老 rig 的 pixel whaleGirl 只剩「画说话人」这一个用途，把同一签名的
// 调用换成 Day3 的高清立绘 + 10 骨骨架；电视里那 28/39 个目录项不动，它们本来就
// 是「旧画质」的对照组。DAY2_HD_SPEAKER=0 可以退回像素版做对比。
// ---------------------------------------------------------------------------
const HD_SPEAKER = process.env.DAY2_HD_SPEAKER !== '0';
if (HD_SPEAKER) {
  const hdDir = process.env.DAY3_SPRITE_DIR ||
    path.resolve(ROOT, '..', 'tools', 'day3制作', 'whale_girl_src');
  const packUrl = pathToFileURL(path.join(hdDir, 'hd_speaker_pack.mjs')).href;
  const { createHdSpeaker } = await import(packUrl);
  const hdSpeaker = await createHdSpeaker({ createCanvas, loadImage, dir: hdDir, onLog: console.log });
  await hdSpeaker.preload();
  const WG = globalThis.WHALE_GIRL || {};
  const baseWhale = WG.whaleGirl;
  WG.whaleGirl = (ctx, x, y, u, o = {}) =>
    hdSpeaker.draw(ctx, x, y, u, o) || baseWhale.call(WG, ctx, x, y, u, o);
  globalThis.WHALE_GIRL = WG;
  globalThis.HD_SPEAKER_PACK = hdSpeaker;
}

const FINAL_SCENE_REL = fs.existsSync(path.join(HERE, 'day2_bonus_final_all.js'))
  ? './day2_bonus_final_all.js'
  : './src/ch/day2_bonus_final_all.js';
const SAMPLE = requireFromHere(FINAL_SCENE_REL);
const TIMING = globalThis.DAY2_BONUS_FINAL_SCENE_TIMING;
if (!FINAL_TIMING || FINAL_TIMING.measured !== true || FINAL_TIMING.voice !== true ||
    FINAL_TIMING.voice_engine !== 'user-provided/final-voice-wav' ||
    FINAL_TIMING.voice_final !== true || FINAL_TIMING.voice_placeholder !== false ||
    FINAL_TIMING.cues?.length !== 9 || FINAL_TIMING.cues[0]?.start !== 0 ||
    !FINAL_TIMING.catalog || !(FINAL_TIMING.catalog.end > FINAL_TIMING.catalog.start) ||
    FINAL_TIMING.catalog.insert_duration !== 0 ||
    FINAL_TIMING.catalog.script_pause_inserted !== false ||
    FINAL_TIMING.cues.some(cue => !Array.isArray(cue.subtitle_segments) ||
      cue.subtitle_segments.length < 2 ||
      cue.subtitle_segments.some(segment => !(segment.end > segment.start) || !segment.text))) {
  throw new Error('final timing gate failed: expected measured 9-cue voice, clause subtitles, and no inserted pause');
}
if (!TIMING || TIMING.measured !== true || TIMING.voice !== true || TIMING.sample_only !== false ||
    TIMING.variant !== VARIANT || TIMING.cues?.length !== 9) {
  throw new Error('final scene timing gate failed');
}
const PIXEL_CATALOG = SAMPLE.PIXEL_ACTION_CATALOG_28 || [];
const POSE_CATALOG = SAMPLE.STICKER_POSE_CATALOG_39 || [];
const rigActionIds = new Set((globalThis.WHALE_GIRL?.ACTION_LIST || []).map(item => item.id));
if (PIXEL_CATALOG.length !== 28 || new Set(PIXEL_CATALOG.map(item => item.id)).size !== 28 ||
    PIXEL_CATALOG.some(item => !rigActionIds.has(item.id))) {
  throw new Error('pixel action catalog gate failed: expected all 28 rig action IDs');
}
if (DAY2_POSE_NAMES.length !== 39 || new Set(DAY2_POSE_NAMES).size !== 39 ||
    POSE_CATALOG.length !== 39 || new Set(POSE_CATALOG.map(item => item.id)).size !== 39 ||
    POSE_CATALOG.some(item => !DAY2_POSE_NAMES.includes(item.id))) {
  throw new Error('sticker pose catalog gate failed: expected all 39 loaded pose IDs');
}
const CATALOG_TIMING = TIMING.catalog || {};
if (CATALOG_TIMING.pixelCount !== 28 || !(CATALOG_TIMING.pixelEnd > CATALOG_TIMING.pixelStart) ||
    CATALOG_TIMING.poseCount !== 39 || !(CATALOG_TIMING.poseEnd > CATALOG_TIMING.poseStart) ||
    CATALOG_TIMING.pixelStart !== CATALOG_TIMING.poseStart ||
    CATALOG_TIMING.pixelEnd !== CATALOG_TIMING.poseEnd ||
    CATALOG_TIMING.insertDuration !== 0 || CATALOG_TIMING.scriptPauseInserted !== false ||
    !(CATALOG_TIMING.dialogueOverlapEnd > CATALOG_TIMING.dialogueOverlapStart)) {
  throw new Error('final side-by-side catalog timing gate failed');
}
if (!TIMELINE?.renderFrame) throw new Error('TIMELINE.renderFrame missing');
CORE.DURATION = Number(TIMING.duration);

const WIDTH = 1280, HEIGHT = 720, SCALE = 1.5, FPS = 30;
const OUT_W = WIDTH * SCALE, OUT_H = HEIGHT * SCALE;
const DURATION = Number(TIMING.duration);
const canvas = createCanvas(OUT_W, OUT_H);
const ctx = canvas.getContext('2d');

const FONT = '"Noto Sans SC","Microsoft YaHei","PingFang SC",sans-serif';
const MODE_LABEL = 'Day2 加更 · 鲸鱼选鱼';
const MODE_NOTE = '现在的鱼学新动作 vs 新设计的鱼';

function text(textValue, x, y, size, color = '#fff', align = 'center', weight = 400) {
  ctx.save();
  ctx.font = `${weight} ${size * SCALE}px ${FONT}`;
  ctx.textAlign = align;
  ctx.textBaseline = 'middle';
  ctx.lineWidth = Math.max(2, size * SCALE * 0.14);
  ctx.strokeStyle = 'rgba(6,20,44,0.92)';
  ctx.strokeText(textValue, x * SCALE, y * SCALE);
  ctx.fillStyle = color;
  ctx.fillText(textValue, x * SCALE, y * SCALE);
  ctx.restore();
}
function shrinkToFit(textValue, maxWidth, size, weight = 700) {
  let s = size;
  ctx.save();
  while (s > 12) {
    ctx.font = `${weight} ${s * SCALE}px ${FONT}`;
    if (ctx.measureText(textValue).width <= maxWidth * SCALE) break;
    s -= 1;
  }
  ctx.restore();
  return s;
}
function measureText(textValue, size, weight = 700) {
  ctx.save();
  ctx.font = `${weight} ${size * SCALE}px ${FONT}`;
  const width = ctx.measureText(textValue).width / SCALE;
  ctx.restore();
  return width;
}
function wrapCaption(textValue, maxWidth, size, weight = 700) {
  ctx.save();
  ctx.font = `${weight} ${size * SCALE}px ${FONT}`;
  const lines = [];
  let line = '';
  for (const ch of textValue) {
    const next = line + ch;
    if (line && ctx.measureText(next).width > maxWidth * SCALE) {
      lines.push(line);
      line = ch;
    } else {
      line = next;
    }
  }
  if (line) lines.push(line);
  ctx.restore();
  return lines;
}
function cueAt(t) {
  return TIMING.cues.find(cue => t >= cue.start && t < cue.end) || null;
}
function subtitleSegmentAt(cue, t) {
  const segments = Array.isArray(cue?.subtitle_segments) ? cue.subtitle_segments : [];
  if (!segments.length) return cue ? { start: cue.start, end: cue.end, text: cue.sub } : null;
  return segments.find(segment => t >= segment.start && t < segment.end) ||
    [...segments].reverse().find(segment => t >= segment.start) ||
    segments[0];
}
function catalogAt(t) {
  if (t >= CATALOG_TIMING.end) return { kind: 'complete' };
  if (t >= CATALOG_TIMING.start && t < CATALOG_TIMING.end) {
    const elapsed = t - CATALOG_TIMING.start;
    const pixelIndex = Math.min(PIXEL_CATALOG.length - 1,
      Math.floor(elapsed / CATALOG_TIMING.pixelItemSeconds));
    const poseIndex = Math.min(POSE_CATALOG.length - 1,
      Math.floor(elapsed / CATALOG_TIMING.poseItemSeconds));
    return {
      kind: 'both',
      pixelIndex,
      pixel: PIXEL_CATALOG[pixelIndex],
      poseIndex,
      pose: POSE_CATALOG[poseIndex]
    };
  }
  return null;
}
function drawSubtitleBox(lines, speaker = '鲸鱼娘') {
  // Day-style presentation: one short timed clause in a compact dialogue
  // box, instead of a full cue wrapped across a full-width black bar.
  const longest = lines.reduce((a, b) => a.length >= b.length ? a : b, '');
  const size = shrinkToFit(longest, 1040, 28, 800);
  const textWidth = Math.max(...lines.map(line => measureText(line, size, 800)));
  const boxW = Math.min(1120, Math.max(360, textWidth + 88));
  const boxH = lines.length > 1 ? 84 : 58;
  const bx = (WIDTH - boxW) / 2;
  const by = HEIGHT - 76 - (boxH - 58);
  ctx.save();
  ctx.beginPath();
  ctx.roundRect(bx * SCALE, by * SCALE, boxW * SCALE, boxH * SCALE, 12 * SCALE);
  ctx.fillStyle = 'rgba(9,22,54,0.92)';
  ctx.fill();
  ctx.strokeStyle = '#48C8FF';
  ctx.lineWidth = 1.6 * SCALE;
  ctx.stroke();
  ctx.beginPath();
  ctx.roundRect((bx + 16) * SCALE, (by - 14) * SCALE, 104 * SCALE, 24 * SCALE, 7 * SCALE);
  ctx.fillStyle = '#1E40AF';
  ctx.fill();
  ctx.strokeStyle = '#FACC15';
  ctx.lineWidth = 1 * SCALE;
  ctx.stroke();
  ctx.restore();
  text(speaker, bx + 68, by - 2, 14, '#FDE68A', 'center', 800);
  const centerY = by + boxH / 2 + 1;
  lines.forEach((line, i) => {
    const y = centerY + (i - (lines.length - 1) / 2) * (size + 7);
    text(line, WIDTH / 2, y, size, '#FFFFFF', 'center', 800);
  });
}
function drawCaption(t) {
  const cue = cueAt(t);
  if (cue) {
    const segment = subtitleSegmentAt(cue, t);
    const lines = wrapCaption(segment.text, 1040, 28, 800);
    drawSubtitleBox(lines, '鲸鱼娘');
    return;
  }
  if (t >= TIMING.cues.at(-1).end) {
    drawSubtitleBox(['左边现在的本鱼，还是右边新设计的鱼？'], '鲸鱼选鱼');
  }
  // During measured inter-cue gaps there is deliberately no flashing
  // full-width catalog bar.  The TV's own numbered tags and bottom channel
  // labels identify the current action/pose while dialogue is present.
}
function drawHud(t) {
  const cue = cueAt(t);
  const cat = catalogAt(t);
  const center = cat?.kind === 'both'
    ? (cue ? '电视对比 · 完整目录播放中' : '完整目录 · 左28动作 / 右39姿势')
    : cat?.kind === 'complete'
      ? '完整目录 · 已全部播完'
      : MODE_NOTE;
  ctx.save();
  ctx.fillStyle = 'rgba(5,15,35,0.82)';
  ctx.fillRect(0, 0, WIDTH * SCALE, 52 * SCALE);
  ctx.fillStyle = '#7DD3FC';
  ctx.fillRect(0, 50 * SCALE, WIDTH * SCALE, 2 * SCALE);
  ctx.restore();
  text(MODE_LABEL, 16, 26, 21, '#FFFFFF', 'left', 800);
  text(center, WIDTH / 2, 26, 18, '#E2E8F0', 'center', 700);
  text(`非官方同人 · AI 生成内容 · ${t.toFixed(1)}s`, WIDTH - 16, 26, 17, '#E2E8F0', 'right', 700);
}
function drawFrame(t) {
  globalThis.__HD_T = t;               // 高清说话人的骨骼动画时钟
  ctx.save();
  ctx.setTransform(SCALE, 0, 0, SCALE, 0, 0);
  ctx.clearRect(0, 0, WIDTH, HEIGHT);
  // 'clean' is required at 1920x1080: the legacy 'pixel' medium overlay
  // samples only the 1280x720 top-left quadrant and would crop the frame.
  TIMELINE.renderFrame(ctx, t, 'clean', { hideHud: true, hideSubtitles: true });
  ctx.restore();
  drawCaption(t);
  drawHud(t);
}

if (STILLS) {
  const dir = path.join(ROOT, 'stills', 'day2_bonus_final');
  fs.mkdirSync(dir, { recursive: true });
  const points = [['f000', null, null, 0]];
  TIMING.cues.forEach((cue, cueIndex) => {
    for (const frac of [0.15, 0.55, 0.88]) {
      points.push([`${cue.id.toLowerCase()}_${String(Math.round(frac * 100)).padStart(2, '0')}`, cueIndex, frac]);
    }
    cue.subtitle_segments.forEach((segment, segmentIndex) => {
      points.push([
        `${cue.id.toLowerCase()}_sub${String(segmentIndex + 1).padStart(2, '0')}`,
        null, null, (segment.start + segment.end) / 2
      ]);
    });
  });
  for (const item of PIXEL_CATALOG) {
    points.push([`act_${String(item.n).padStart(2, '0')}_${item.id}`, null, null,
      CATALOG_TIMING.pixelStart + (item.n - 0.5) * CATALOG_TIMING.pixelItemSeconds]);
  }
  for (const item of POSE_CATALOG) {
    points.push([`pose_${String(item.n).padStart(2, '0')}_${item.id}`, null, null,
      CATALOG_TIMING.poseStart + (item.n - 0.5) * CATALOG_TIMING.poseItemSeconds]);
  }
  points.push(['b05_b06_transition', null, null, TIMING.cues[4].end + 0.2]);
  points.push(['catalog_overlap_b06', null, null,
    (CATALOG_TIMING.dialogueOverlapStart + CATALOG_TIMING.dialogueOverlapEnd) / 2]);
  points.push(['catalog_complete', null, null, CATALOG_TIMING.end + 0.1]);
  points.push(['end_hold', null, null, TIMING.cues.at(-1).end + 0.8]);
  for (const [name, cueIndex, frac, absoluteT] of points) {
    const cue = cueIndex === null ? null : TIMING.cues[cueIndex];
    const t = absoluteT ?? (cue.start + (cue.end - cue.start) * frac);
    drawFrame(t);
    const file = path.join(dir, `${name}.png`);
    await fs.promises.writeFile(file, canvas.toBuffer('image/png'));
    console.log(`[day2-bonus-final] still ${name} t=${t.toFixed(3)} -> ${file}`);
  }
  process.exit(0);
}

fs.mkdirSync(path.dirname(OUT), { recursive: true });
const FFMPEG = process.env.FFMPEG_BIN || process.env.FFMPEG_PATH || 'ffmpeg';
const AUDIO_TRACK = path.join(ROOT, 'assets', 'day2_bonus_final_track.wav');
if (!fs.existsSync(AUDIO_TRACK)) throw new Error(`final audio track missing: ${AUDIO_TRACK}`);
const args = [
  '-y',
  '-f', 'rawvideo', '-pix_fmt', 'rgba', '-s', `${OUT_W}x${OUT_H}`, '-r', String(FPS),
  '-i', 'pipe:0',
  '-i', AUDIO_TRACK,
  '-map', '0:v:0', '-map', '1:a:0',
  '-c:v', 'libx264', '-preset', 'medium', '-tune', 'animation', '-crf', '17',
  '-pix_fmt', 'yuv420p', '-profile:v', 'high',
  '-c:a', 'aac', '-b:a', '160k', '-ar', '48000', '-ac', '2',
  '-shortest', '-movflags', '+faststart', '-r', String(FPS),
  '-metadata', 'title=Day2加更《鲸鱼选鱼》最终配音版',
  '-metadata', 'comment=Measured user-provided final voice WAV; synthesis engine not embedded/verified; left 28 pixel actions, right 39 TV poses',
  OUT
];
const ff = spawn(FFMPEG, args, { stdio: ['pipe', 'inherit', 'inherit'] });
const ffmpegDone = new Promise((resolve, reject) => {
  ff.on('error', reject);
  ff.on('close', code => code === 0 ? resolve() : reject(new Error(`ffmpeg exited ${code}`)));
});
ffmpegDone.catch(() => {});
const total = Math.ceil(DURATION * FPS);
for (let f = 0; f < total; f++) {
  const t = f / FPS;
  drawFrame(t);
  const rgbaFrame = ctx.getImageData(0, 0, OUT_W, OUT_H).data;
  const ok = ff.stdin.write(Buffer.from(rgbaFrame.buffer, rgbaFrame.byteOffset, rgbaFrame.byteLength));
  if (!ok) await new Promise(resolve => ff.stdin.once('drain', resolve));
  if (f % 90 === 0) console.log(`[day2-bonus-final] frame ${f}/${total} (${(100 * f / total).toFixed(1)}%)`);
}
ff.stdin.end();
await ffmpegDone;
console.log(`[day2-bonus-final] done frames=${total} duration=${DURATION.toFixed(3)}s out=${OUT}`);
